import "aos/dist/aos.css";
import {
    FaLightbulb,
    FaCopyright,
    FaTrademark,
    FaCogs,
    FaClipboardList,
    FaWhatsapp,
} from "react-icons/fa";
import { Client1, Client2, Client3, Client4 } from "../../asset/image";

function IntellectualProperty() {
    //-----------------------STATE VIEWS-----------------------//
    const ipServices = [
        {
            title: "Trademark (Merek)",
            description:
                "Pendaftaran, perpanjangan, dan perlindungan merek dagang untuk menjaga identitas dan reputasi bisnis Anda.",
            icon: FaTrademark,
        },
        {
            title: "Copyright (Hak Cipta)",
            description:
                "Perlindungan hukum atas karya intelektual seperti konten digital, karya tulis, desain, dan software.",
            icon: FaCopyright,
        },
        {
            title: "Patent",
            description:
                "Pendampingan pendaftaran paten untuk melindungi inovasi, teknologi, dan penemuan bernilai komersial.",
            icon: FaLightbulb,
        },
        {
            title: "Industrial Design",
            description:
                "Perlindungan desain industri untuk memastikan tampilan visual produk tidak disalahgunakan pihak lain.",
            icon: FaCogs,
        },
        {
            title: "IP Consultation & Management",
            description:
                "Konsultasi dan pengelolaan kekayaan intelektual secara strategis untuk mendukung pertumbuhan bisnis.",
            icon: FaClipboardList,
        },
    ];

    const clients = [
        { name: "Client 1", logo: Client1 },
        { name: "Client 2", logo: Client2 },
        { name: "Client 3", logo: Client3 },
        { name: "Client 4", logo: Client4 },
    ];

    const WA_NUMBER = "6281213094426";

    //------------------------FUNCTIONS------------------------//
    const getWaLink = (serviceName: string) => {
        const message = `Halo Regarde,%0ASaya ingin berkonsultasi terkait layanan ${serviceName}.%0AMohon informasinya. Terima kasih.`;
        return `https://wa.me/${WA_NUMBER}?text=${message}`;
    };
    //------------------------FUNCTIONS------------------------//

    return (
        <div className="pt-24">
            {/* INTELLECTUAL PROPERTY DETAIL */}
            <section data-aos="zoom-out" className="pb-24 bg-white">
                <div className="w-11/12 md:w-8/12 mx-auto text-center">

                    {/* ICON */}
                    <div className="flex justify-center mb-6">
                        <div className="w-20 h-20 rounded-full bg-sky-100 flex items-center justify-center">
                            <FaLightbulb className="text-sky-700 text-4xl" />
                        </div>
                    </div>

                    {/* TITLE */}
                    <h2 className="text-4xl font-black text-sky-900 mb-4">
                        Intellectual Property
                    </h2>

                    {/* DESCRIPTION */}
                    <p className="text-gray-600 max-w-2xl mx-auto mb-14">
                        Layanan perlindungan dan pengelolaan kekayaan intelektual
                        untuk memastikan hak, nilai, dan keberlanjutan aset
                        intelektual Anda.
                    </p>

                    {/* SUB SERVICES */}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8 text-left">
                        {ipServices.map((service, i) => {
                            const Icon = service.icon;
                            return (
                                <div
                                    key={i}
                                    data-aos="fade-up"
                                    data-aos-delay={i * 100}
                                    className="bg-white rounded-xl border border-gray-200 p-6 hover:shadow-md transition flex flex-col"
                                >
                                    {/* CONTENT */}
                                    <div className="flex items-start gap-4">
                                        <div className="text-sky-600 text-2xl mt-1">
                                            <Icon />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-sky-900">
                                                {service.title}
                                            </h3>
                                            <p className="text-sm text-gray-600 mt-1">
                                                {service.description}
                                            </p>
                                        </div>
                                    </div>

                                    {/* WA BUTTON */}
                                    <a
                                        href={getWaLink(service.title)}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="mt-auto self-end w-10 h-10 rounded-full bg-green-600 text-white flex items-center justify-center hover:bg-green-700 transition"
                                        aria-label="Chat via WhatsApp"
                                    >
                                        <FaWhatsapp className="text-lg" />
                                    </a>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </section>

            {/* OUR CLIENTS */}
            <section className="py-20">
                <div className="w-11/12 md:w-9/12 mx-auto text-center">
                    <h2
                        data-aos="zoom-in"
                        className="text-4xl font-black text-sky-900 mb-12">
                        Our Clients
                    </h2>
                    <div className="flex flex-wrap justify-center gap-8">
                        {clients.map((client, i) => (
                            <div key={i}
                                data-aos="fade-up"
                                data-aos-delay={i * 40}
                                className="flex items-center justify-center">
                                <img
                                    src={client.logo}
                                    alt={client.name}
                                    className="h-10 md:h-12 object-contain opacity-90 hover:opacity-100 transition"
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </div>
    );
}

export default IntellectualProperty;
